import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.57.4';
import { verifyWebsiteBeforeDelivery } from './_shared/website.ts';

const noCache={'Cache-Control':'no-store','Referrer-Policy':'no-referrer','X-Robots-Tag':'noindex, nofollow','X-Content-Type-Options':'nosniff','Cross-Origin-Resource-Policy':'cross-origin','Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET, OPTIONS','Access-Control-Allow-Headers':'Content-Type'};
const error=(message:string,status:number)=>new Response(message,{status,headers:{...noCache,'Content-Type':'text/plain; charset=utf-8'}});
const sha256=async(s:string)=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))].map(b=>b.toString(16).padStart(2,'0')).join('');
const validPath=(s:string)=>s.length>0&&s.length<=300&&!s.startsWith('/')&&!s.includes('\\')&&!s.split('/').some(p=>p==='..'||p==='.'||p.startsWith('.git'))&&!s.startsWith('docs/')&&/^[\w.\-/ ]+$/.test(s);
function proxy(raw:string,path:string,base:string){
 if(!raw||/^(?:https?:|data:|mailto:|tel:|javascript:|blob:|\/\/|#)/i.test(raw))return raw;
 try{
  const u=new URL(raw,'https://preview.invalid/'+path);
  if(u.origin!=='https://preview.invalid')return raw;
  const next=decodeURIComponent(u.pathname.slice(1));
  if(!validPath(next))return raw;
  return base+'&path='+encodeURIComponent(next)+(u.hash||'');
 }catch{return raw}
}
function rewrite(s:string,path:string,base:string,css:boolean){
 const viewer=(raw:string)=>{
  if(!/\.html?(?:[?#]|$)/i.test(raw))return proxy(raw,path,base);
  const ref=proxy(raw,path,base);
  if(ref===raw)return raw;
  const param=ref.slice(base.length+1);
  return 'https://sho-web-support.netlify.app/website-preview.html?'+base.split('?')[1]+'&'+param;
 };
 if(!css){
   s=s.replace(/\b(href|src|poster|action)\s*=\s*(["'])(.*?)\2/gi,(_,attr,q,v)=>attr+'='+q+(attr.toLowerCase()==='href'?viewer(v):proxy(v,path,base)).replace(/&/g,'&amp;')+q);
   s=s.replace(/\bsrcset\s*=\s*(["'])(.*?)\1/gi,(_,q,v)=>'srcset='+q+v.split(',').map((part:string)=>{const m=part.trim().match(/^(\S+)(\s+.*)?$/);return m?proxy(m[1],path,base).replace(/&/g,'&amp;')+(m[2]||''):part}).join(', ')+q);
 }
 return s.replace(/url\(\s*(["']?)([^"')]+)\1\s*\)/gi,(_,q,v)=>'url('+q+proxy(v.trim(),path,base)+q+')');
}
const types:Record<string,string>={html:'text/html; charset=utf-8',htm:'text/html; charset=utf-8',css:'text/css; charset=utf-8',js:'text/javascript; charset=utf-8',json:'application/json',svg:'image/svg+xml',png:'image/png',webp:'image/webp',avif:'image/avif',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',ico:'image/x-icon',woff:'font/woff',woff2:'font/woff2',mp4:'video/mp4',pdf:'application/pdf',txt:'text/plain; charset=utf-8'};
Deno.serve(async(req)=>{
 try{
  if(req.method==='OPTIONS')return new Response('ok',{headers:noCache});
  if(req.method!=='GET')return error('Method not allowed',405);
  const u=new URL(req.url),id=u.searchParams.get('id')||'',key=u.searchParams.get('key')||'',path=u.searchParams.get('path')||'index.html';
  if(!/^[A-Za-z0-9_-]{3,32}$/.test(id)||!/^[A-Za-z0-9_-]{20,200}$/.test(key)||!validPath(path))return error('Invalid preview URL',403);
  const db=createClient(Deno.env.get('SUPABASE_URL')||'',Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'',{auth:{persistSession:false}});
  const {data:site,error:dbError}=await db.from('website_sites').select('repo_full_name,publish_branch,preview_branch,status,preview_access_token_hash,review_access_token_hash').eq('site_id',id).maybeSingle();
  if(dbError)throw dbError;
  const hash=await sha256(key);
  if(!site?.repo_full_name||(hash!==site.preview_access_token_hash&&hash!==site.review_access_token_hash))return error('Preview link expired',403);
  if(site.status==='live')return error('Preview ended. Visit the public site.',403);
  if(u.searchParams.get('qa')==='1'){
    const {data:order,error:orderError}=await db.from('website_orders').select('plan,template_style').eq('site_id',id).maybeSingle();
    if(orderError)throw orderError;
    try{
      const check=await verifyWebsiteBeforeDelivery(site.repo_full_name,site.preview_branch||site.publish_branch||'main',order?.plan==='semi'?String(order.template_style||''):'');
      return new Response(JSON.stringify({ok:true,css:check.inline_css,files:check.files}),{status:200,headers:{...noCache,'Content-Type':'application/json; charset=utf-8'}});
    }catch(e){return new Response(JSON.stringify({ok:false,error:String((e as Error).message||e).slice(0,300)}),{status:422,headers:{...noCache,'Content-Type':'application/json; charset=utf-8'}})}
  }
  const m=String(site.repo_full_name).match(/^([A-Za-z0-9_.-]+)\/([A-Za-z0-9_.-]+)$/);
  if(!m)return error('Missing preview repository',404);
  const token=Deno.env.get('GITHUB_PAGES_TOKEN')||'';
  if(!token)return error('Preview unavailable',503);
  const endpoint='https://api.github.com/repos/'+m[1]+'/'+m[2]+'/contents/'+path.split('/').map(encodeURIComponent).join('/')+'?ref='+encodeURIComponent(site.preview_branch||site.publish_branch||'main');
  const github=await fetch(endpoint,{headers:{Authorization:'Bearer '+token,'X-GitHub-Api-Version':'2022-11-28',Accept:'application/vnd.github.raw+json'}});
  if(!github.ok)return error('Preview file unavailable',github.status===404?404:502);
  const limit=8_000_000;
  const declaredSize=Number(github.headers.get('content-length')||0);
  if(declaredSize>limit)return error('Preview file too large',413);
  const buffer=await github.arrayBuffer();
  if(buffer.byteLength>limit)return error('Preview file too large',413);
  let bytes=new Uint8Array(buffer);
  // GitHub Contents API may return a JSON/base64 envelope even with the raw
  // media type. Normalize it before assigning the image MIME type.
  if(bytes[0]===123 && (github.headers.get('content-type')||'').includes('json')){
    const obj=JSON.parse(new TextDecoder().decode(bytes));
    if(obj?.encoding==='base64' && typeof obj.content==='string'){
      const raw=atob(obj.content.replace(/\s+/g,''));
      if(raw.length>limit)return error('Preview file too large',413);
      bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));
    }
  }
  const ext=(path.match(/\.([A-Za-z0-9]+)$/)?.[1]||'html').toLowerCase(),ct=types[ext]||'application/octet-stream';
  if(ext==='png' && !(bytes.length>=8&&bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71&&bytes[4]===13&&bytes[5]===10&&bytes[6]===26&&bytes[7]===10))return error('Preview file is not a PNG image',502);
  if((ext==='jpg'||ext==='jpeg') && !(bytes.length>=3&&bytes[0]===255&&bytes[1]===216&&bytes[2]===255))return error('Preview file is not a JPEG image',502);
  if(ext==='webp' && !(bytes.length>=12&&new TextDecoder().decode(bytes.slice(0,4))==='RIFF'&&new TextDecoder().decode(bytes.slice(8,12))==='WEBP'))return error('Preview file is not a WebP image',502);
  if(ext==='html'||ext==='htm'||ext==='css'){
   // req.url is an internal Edge Runtime URL in some deployments (http://.../website-preview).
   // Never use it for browser-facing asset links: use the public HTTPS Functions URL.
   const publicRoot=new URL(Deno.env.get('SUPABASE_URL')||'');
   if(publicRoot.protocol!=='https:'||!publicRoot.hostname.endsWith('.supabase.co'))throw new Error('Invalid public Supabase URL');
   const base=publicRoot.origin+'/functions/v1/website-preview?id='+encodeURIComponent(id)+'&key='+encodeURIComponent(key);
   const content=rewrite(new TextDecoder().decode(bytes),path,base,ext==='css');
   return ext==='css'?new Response(content,{status:200,headers:{...noCache,'Content-Type':ct}}):new Response(JSON.stringify({html:content}),{status:200,headers:{...noCache,'Content-Type':'application/json; charset=utf-8'}});
  }
  return new Response(bytes,{status:200,headers:{...noCache,'Content-Type':ct}});
 }catch(e){console.error('website-preview:',String(e));return error('Preview unavailable',500);}
});

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.57.4';

export const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

export function json(data: unknown, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' },
  });
}

export function adminClient() {
  const url = Deno.env.get('SUPABASE_URL');
  const key = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
  if (!url || !key) throw new Error('Supabase server secrets are missing.');
  return createClient(url, key, { auth: { persistSession: false, autoRefreshToken: false } });
}

export function bearer(req: Request) {
  const value = req.headers.get('authorization') || '';
  return value.startsWith('Bearer ') ? value.slice(7).trim() : '';
}

export async function getUser(req: Request, admin = adminClient()) {
  const token = bearer(req);
  if (!token) return null;
  const { data, error } = await admin.auth.getUser(token);
  if (error) return null;
  return data.user || null;
}

export async function isAdmin(admin: ReturnType<typeof adminClient>, userId: string) {
  const { data, error } = await admin.from('website_admins').select('user_id').eq('user_id', userId).maybeSingle();
  if (error) throw error;
  return Boolean(data);
}

export async function siteRole(admin: ReturnType<typeof adminClient>, userId: string, siteId: string) {
  if (await isAdmin(admin, userId)) return 'admin';
  const { data, error } = await admin
    .from('website_site_users')
    .select('role')
    .eq('site_id', siteId)
    .eq('user_id', userId)
    .maybeSingle();
  if (error) throw error;
  return data?.role || null;
}

let cachedLineToken = '';
let cachedLineTokenUntil = 0;

async function getLineAccessToken() {
  const fixed = Deno.env.get('LINE_CHANNEL_ACCESS_TOKEN') || '';
  if (fixed) return fixed;

  const now = Date.now();
  if (cachedLineToken && now < cachedLineTokenUntil) return cachedLineToken;

  const clientId = Deno.env.get('LINE_CHANNEL_ID') || '';
  const clientSecret = Deno.env.get('LINE_CHANNEL_SECRET') || '';
  if (!clientId || !clientSecret) return '';

  const body = new URLSearchParams({
    grant_type: 'client_credentials',
    client_id: clientId,
    client_secret: clientSecret,
  });
  const response = await fetch('https://api.line.me/oauth2/v3/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body,
  });
  if (!response.ok) {
    console.error('LINE token issue failed', response.status, await response.text());
    return '';
  }

  const data = await response.json().catch(() => ({}));
  cachedLineToken = String(data?.access_token || '');
  const expiresIn = Math.max(60, Number(data?.expires_in || 900));
  cachedLineTokenUntil = now + Math.max(60, expiresIn - 60) * 1000;
  return cachedLineToken;
}

export async function getLineMessagingToken() {
  return getLineAccessToken();
}

export async function linePush(to: string | null | undefined, text: string) {
  const token = await getLineAccessToken();
  if (!token || !to) return { skipped: true };
  const response = await fetch('https://api.line.me/v2/bot/message/push', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
    body: JSON.stringify({ to, messages: [{ type: 'text', text: text.slice(0, 5000) }] }),
  });
  if (!response.ok) {
    console.error('LINE push failed', response.status, await response.text());
    return { skipped: false, ok: false };
  }
  return { skipped: false, ok: true };
}

export async function notifyOwner(text: string) {
  let ownerUserId = Deno.env.get('LINE_OWNER_USER_ID') || '';
  if (!ownerUserId) {
    try {
      const admin = adminClient();
      const { data } = await admin.from('website_settings').select('value').eq('key', 'line_owner').maybeSingle();
      ownerUserId = String(data?.value?.user_id || '');
    } catch (error) {
      console.error('Failed to resolve LINE owner user ID', error);
    }
  }
  return linePush(ownerUserId, text);
}


export async function triggerWebsiteWorker(siteId: string) {
  const url = Deno.env.get('SUPABASE_URL') || '';
  const key = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';
  if (!url || !key) {
    console.error('website-worker trigger skipped: Supabase server secrets are missing.');
    return { ok: false, skipped: true };
  }
  const response = await fetch(`${url}/functions/v1/website-worker`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${key}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ site_id: siteId }),
  });
  if (!response.ok) {
    console.error('website-worker trigger failed', response.status, await response.text());
    return { ok: false, status: response.status };
  }
  return { ok: true };
}


function githubHeaders() {
  const token = Deno.env.get('GITHUB_PAGES_TOKEN');
  if (!token) throw new Error('GITHUB_PAGES_TOKEN is missing.');
  return {
    Accept: 'application/vnd.github+json',
    Authorization: `Bearer ${token}`,
    'X-GitHub-Api-Version': '2026-03-10',
    'Content-Type': 'application/json',
  };
}

function parseRepo(repoFullName: string) {
  const match = String(repoFullName || '').match(/^([^/]+)\/([^/]+)$/);
  if (!match) throw new Error('Invalid GitHub repository name.');
  return { owner: match[1], repo: match[2] };
}


export async function verifyWebsiteBeforeDelivery(repoFullName: string, branch = 'main', expectedSemiTheme = '') {
  const {owner,repo}=parseRepo(repoFullName);
  const base='https://api.github.com/repos/'+encodeURIComponent(owner)+'/'+encodeURIComponent(repo);
  const headers=githubHeaders();
  const [treeResponse,htmlResponse]=await Promise.all([
    fetch(base+'/git/trees/'+encodeURIComponent(branch)+'?recursive=1',{headers}),
    fetch(base+'/contents/index.html?ref='+encodeURIComponent(branch),{
      headers:{...headers,Accept:'application/vnd.github.raw+json'}
    })
  ]);
  if(!treeResponse.ok||!htmlResponse.ok)throw new Error('公開前検査：GitHubの制作ファイルを取得できません。');
  const tree=await treeResponse.json();
  if(tree.truncated)throw new Error('公開前検査：ファイル一覧が多すぎるため確認できません。');
  const files=new Map<string,number>((tree.tree||[]).filter((x:any)=>x.type==='blob').map((x:any)=>[x.path,Number(x.size||0)]));
  if(!files.has('index.html'))throw new Error('公開前検査：index.html がありません。');
  const html=await htmlResponse.text();
  if(!/<html\b/i.test(html)||!/<body\b/i.test(html)||html.length<350)throw new Error('公開前検査：ホームページのHTMLが不正です。');
  if(!/name\s*=\s*["']viewport["']/i.test(html))throw new Error('公開前検査：スマホ表示の指定がありません。');
  if(expectedSemiTheme&&!html.includes('data-theme="'+expectedSemiTheme+'"'))throw new Error('公開前検査：選択したテンプレートのデザインと一致しません。');
  const missing:string[]=[];
  let cssFound=/<style\b/i.test(html);
  const verify=(ref:string,kind:string)=>{
    if(!ref.trim()){missing.push(kind+' の参照が空です');return}
    if(/^(?:https?:|data:|blob:|mailto:|tel:|#|\/\/)/i.test(ref))return;
    try{
      const parsed=new URL(ref,'https://local.invalid/');
      if(parsed.origin!=='https://local.invalid')return;
      const path=decodeURIComponent(parsed.pathname.slice(1));
      if(!path||path.includes('..')||!files.has(path)||files.get(path)===0)missing.push(kind+': '+path);
    }catch{missing.push(kind+' のパスが不正です');}
  };
  for(const match of html.matchAll(/<img\b[^>]*>/gi)){
    const ref=match[0].match(/\bsrc\s*=\s*["']([^"']*)["']/i)?.[1];
    if(ref===undefined)missing.push('画像の参照がありません');else verify(ref,'画像');
  }
  for(const match of html.matchAll(/<script\b[^>]*>/gi)){
    const ref=match[0].match(/\bsrc\s*=\s*["']([^"']*)["']/i)?.[1];
    if(ref!==undefined)verify(ref,'動作ファイル');
  }
  for(const match of html.matchAll(/<link\b[^>]*>/gi)){
    const tag=match[0];
    if(!/\brel\s*=\s*["'][^"']*\bstylesheet\b/i.test(tag))continue;
    cssFound=true;
    const ref=tag.match(/\bhref\s*=\s*["']([^"']*)["']/i)?.[1];
    if(ref===undefined)missing.push('CSSの参照がありません');else verify(ref,'CSS');
  }
  if(!cssFound)missing.push('スタイルシートがありません');
  if(missing.length)throw new Error('公開前検査で不足が見つかりました：'+missing.slice(0,8).join(' / '));
  return {ok:true,files:files.size,inline_css:/<style\b/i.test(html)};
}

export async function publishApprovedStagedBranch(repoFullName:string,liveBranch:string,stagedBranch:string|null|undefined) {
  if(!stagedBranch)return;
  if(!/^sho-review-[a-f0-9-]{8,50}$/.test(stagedBranch)||stagedBranch===liveBranch)throw new Error('Invalid staged branch.');
  const {owner,repo}=parseRepo(repoFullName);
  const response=await fetch(`https://api.github.com/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}/merges`,{
    method:'POST',
    headers:githubHeaders(),
    body:JSON.stringify({base:liveBranch,head:stagedBranch,commit_message:'Publish customer-approved website update'}),
  });
  if(response.status!==201&&response.status!==204)throw new Error(`GitHub staged update merge failed: ${response.status} ${(await response.text()).slice(0,500)}`);
}

export async function setGithubPagesSource(repoFullName: string, branch = 'main', path: '/' | '/docs' = '/') {
  const { owner, repo } = parseRepo(repoFullName);
  const base = `https://api.github.com/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}/pages`;
  const headers = githubHeaders();
  // Draft sites are kept in private repositories. Publishing requires a public Pages repository.
  if (path === '/') {
    const repoUrl = `https://api.github.com/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}`;
    const infoResponse = await fetch(repoUrl, { headers });
    if (!infoResponse.ok) throw new Error(`GitHub repository lookup failed: ${infoResponse.status}`);
    const info = await infoResponse.json();
    if (info.private) {
      const visibility = await fetch(repoUrl, {
        method: 'PATCH', headers,
        body: JSON.stringify({ private: false }),
      });
      if (!visibility.ok) throw new Error(`GitHub repository publish failed: ${visibility.status} ${(await visibility.text()).slice(0,300)}`);
    }
  }
  const current = await fetch(base, { headers });

  if (current.status === 404) {
    const created = await fetch(base, {
      method: 'POST',
      headers,
      body: JSON.stringify({ build_type: 'legacy', source: { branch, path } }),
    });
    if (!created.ok) throw new Error(`GitHub Pages create failed: ${created.status} ${await created.text()}`);
    return await created.json().catch(() => ({}));
  }

  if (!current.ok) throw new Error(`GitHub Pages read failed: ${current.status} ${await current.text()}`);

  const updated = await fetch(base, {
    method: 'PUT',
    headers,
    body: JSON.stringify({ build_type: 'legacy', source: { branch, path } }),
  });
  if (!updated.ok) throw new Error(`GitHub Pages update failed: ${updated.status} ${await updated.text()}`);
  return { ok: true };
}

export async function setGithubPagesDomain(repoFullName: string, cname: string | null) {
  const { owner, repo } = parseRepo(repoFullName);
  const response = await fetch(
    `https://api.github.com/repos/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}/pages`,
    {
      method: 'PUT',
      headers: githubHeaders(),
      body: JSON.stringify({ cname: cname || null }),
    },
  );
  if (!response.ok) throw new Error(`GitHub Pages domain update failed: ${response.status} ${await response.text()}`);
  return { ok: true };
}
